-- Preserve deleted occurrences so the same schedule/date cannot be generated twice.
ALTER TABLE eam_maintenance_task
  ADD COLUMN deleted TINYINT NOT NULL DEFAULT 0 COMMENT '逻辑删除标记',
  ADD COLUMN deleted_at DATETIME(6) NULL COMMENT '删除时间',
  ADD COLUMN deleted_by BIGINT NULL COMMENT '删除操作人ID';

-- All business queries use this projection; deleted tasks retain audit and unique occurrence keys.
CREATE OR REPLACE VIEW v_maintenance_task AS SELECT t.id,t.tenant_id,t.code,t.plan_id,t.equipment_id,t.company_id,t.department_id,t.owner_id,t.status,t.row_version,t.created_at,t.updated_at,t.type_id,t.schedule_id,t.due_date,t.expires_date,JSON_SET(t.snapshot,'$.owners',COALESCE((SELECT JSON_ARRAYAGG(CAST(r.user_id AS CHAR)) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM eam_maintenance_task_person r WHERE r.tenant_id=t.tenant_id AND r.task_id=t.id AND r.role_code='owner' LIMIT 1),JSON_ARRAY()),'$.reviewers',COALESCE((SELECT JSON_ARRAYAGG(CAST(r.user_id AS CHAR)) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM eam_maintenance_task_person r WHERE r.tenant_id=t.tenant_id AND r.task_id=t.id AND r.role_code='reviewer' LIMIT 1),JSON_ARRAY())) snapshot,IF(e.task_id IS NULL,NULL,JSON_OBJECT('description',COALESCE(e.`description`,''),'startedAt',COALESCE(DATE_FORMAT(e.`started_at`,'%Y-%m-%dT%H:%i:%s.%f'),''),'startAt',COALESCE(DATE_FORMAT(e.`work_start_at`,'%Y-%m-%dT%H:%i:%s.%f'),''),'endAt',COALESCE(DATE_FORMAT(e.`work_end_at`,'%Y-%m-%dT%H:%i:%s.%f'),''),'items',COALESCE((SELECT JSON_ARRAYAGG(r.item_view) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM v_maintenance_execution_item r WHERE r.tenant_id=t.tenant_id AND r.task_id=t.id LIMIT 1),JSON_ARRAY()),'attachments',COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('id',r.file_id,'name',r.name_snapshot,'contentType',r.content_type,'size',r.size_bytes,'url',r.url_snapshot)) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM eam_maintenance_execution_file r WHERE r.tenant_id=t.tenant_id AND r.task_id=t.id AND r.stage_code='execution' LIMIT 1),JSON_ARRAY()),'acceptance',JSON_OBJECT('reviewerId',COALESCE(CAST(e.reviewer_id AS CHAR),''),'reviewer',COALESCE(e.reviewer_name,''),'reviewedAt',COALESCE(DATE_FORMAT(e.reviewed_at,'%Y-%m-%dT%H:%i:%s.%f'),''),'decision',COALESCE(e.`review_decision`,''),'description',COALESCE(e.`review_description`,''),'score',e.`acceptance_score`,'attachments',COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('id',r.file_id,'name',r.name_snapshot,'contentType',r.content_type,'size',r.size_bytes,'url',r.url_snapshot)) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM eam_maintenance_execution_file r WHERE r.tenant_id=t.tenant_id AND r.task_id=t.id AND r.stage_code='acceptance' LIMIT 1),JSON_ARRAY())),'collaborators',COALESCE((SELECT JSON_ARRAYAGG(CAST(r.user_id AS CHAR)) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM eam_maintenance_task_person r WHERE r.tenant_id=t.tenant_id AND r.task_id=t.id AND r.role_code='collaborator' LIMIT 1),JSON_ARRAY()))) result FROM eam_maintenance_task t LEFT JOIN eam_maintenance_execution e ON e.tenant_id=t.tenant_id AND e.task_id=t.id WHERE t.deleted=0;
